<template><div class="page"><v-card flat class="hero pa-5 mb-4"><div class="d-flex align-center flex-wrap"><div><div class="text-overline">SALES</div><h1 class="text-h5 font-weight-bold">Bookings</h1><div class="grey--text">Manage reservations, confirmations and completed sales.</div></div><v-spacer/><v-btn color="#165134" dark @click="dialog=true">New Booking</v-btn></div></v-card><v-card flat class="pa-3 mb-4"><v-row dense><v-col cols="12" md="6"><v-text-field v-model="search" outlined dense clearable prepend-inner-icon="mdi-magnify" label="Search booking or customer" @keyup.enter="load"/></v-col><v-col cols="12" md="3"><v-select v-model="status" :items="statuses" outlined dense clearable label="Status" @change="load"/></v-col></v-row></v-card><v-card flat><v-data-table :headers="headers" :items="items" :loading="loading"><template v-slot:item.status="{item}"><v-chip x-small dark :color="color(item.status)">{{item.status}}</v-chip></template><template v-slot:item.final_price="{item}">{{money(item.final_price)}}</template><template v-slot:item.remaining_amount="{item}"><span :class="{'error--text':Number(item.remaining_amount)>0}">{{money(item.remaining_amount)}}</span></template><template v-slot:item.actions="{item}"><v-btn v-if="item.status==='reserved'" icon small title="Confirm" @click="transition(item,'confirm')"><v-icon small>mdi-check</v-icon></v-btn><v-btn v-if="['reserved','confirmed'].includes(item.status)" icon small title="Cancel" @click="transition(item,'cancel')"><v-icon small>mdi-close</v-icon></v-btn><v-btn v-if="item.status==='confirmed' && Number(item.remaining_amount)<=0" icon small title="Complete" @click="transition(item,'complete')"><v-icon small>mdi-check-circle</v-icon></v-btn></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="600"><v-card><v-card-title>New Booking</v-card-title><v-card-text><v-alert outlined type="info" dense>Enter IDs from your customer and property records.</v-alert><v-row><v-col cols="12" md="6"><v-text-field v-model="form.customer_id" type="number" outlined dense label="Customer ID *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.property_id" type="number" outlined dense label="Property ID *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.sales_agent_id" type="number" outlined dense label="Sales Agent ID"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.discount" type="number" outlined dense label="Discount"/></v-col><v-col cols="12"><v-textarea v-model="form.notes" outlined dense label="Notes"/></v-col></v-row></v-card-text><v-card-actions><v-spacer/><v-btn text @click="dialog=false">Cancel</v-btn><v-btn color="#165134" dark :loading="saving" @click="save">Reserve Property</v-btn></v-card-actions></v-card></v-dialog></div></template><script>import api from '../../../services/api';export default{name:'Bookings',data(){return{loading:false,saving:false,dialog:false,search:'',status:null,items:[],statuses:['reserved','confirmed','completed','cancelled'],headers:[{text:'Booking #',value:'booking_number'},{text:'Customer',value:'customer.name'},{text:'Property',value:'property.property_number'},{text:'Status',value:'status'},{text:'Final Price',value:'final_price'},{text:'Remaining',value:'remaining_amount'},{text:'Actions',value:'actions',sortable:false}],form:{customer_id:null,property_id:null,sales_agent_id:null,discount:0,notes:''}}},mounted(){this.load()},methods:{async load(){this.loading=true;try{const r=await api.get('/bookings',{params:{search:this.search,status:this.status,per_page:100}});this.items=r.data.data||[]}finally{this.loading=false}},money(v){return new Intl.NumberFormat('en-PK',{maximumFractionDigits:0}).format(Number(v||0))},color(s){return{reserved:'orange',confirmed:'blue',completed:'success',cancelled:'grey'}[s]||'grey'},async save(){this.saving=true;try{await api.post('/bookings',this.form);this.dialog=false;await this.load()}catch(e){this.$root.$emit('show-error',e.response?.data?.message||'Unable to create booking.')}finally{this.saving=false}},async transition(item,action){try{await api.post('/bookings/'+item.id+'/'+action);await this.load()}catch(e){this.$root.$emit('show-error',e.response?.data?.message||'Unable to update booking.')}}}}</script><style scoped>.page{width:100%}.hero{border-left:4px solid #165134}</style>